-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): seismolord.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/seismolord.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE
--   bulk_shift_ms was stated in the prompt ('arriving 8 ms late') and the Shift
--   explorer subtitle, so the answer was given before any scan; the prompt and
--   panel no longer state the lag and the key, value and tolerance stay. corr
--   graded the correlation at the winning lag, which is exactly 1 by
--   construction (the observed trace is the synthetic shifted), so typing 1
--   passed. It is replaced by the correlation at zero lag, before any shift,
--   0.6217418028775199, printed to six decimals by the same scan (ShiftExplorer
--   'Correlation at zero lag' tile), tol 0.0005. The prompt's em dash is
--   removed.
--   RE-KEY corr (expected 1, tol 0.01)
--       -> corr_zero_lag 'Correlation at zero lag, before any shift' -, expected 0.6217418028775199, tol 0.0005
--   PROMPT was: the 25 Hz synthetic arriving 8 ms late.
--   PROMPT now: the 25 Hz synthetic arriving late by a lag this brief does not
--   state.
--   PROMPT was: the suggested shift and its correlation.
--   PROMPT now: the suggested shift, and the correlation at zero lag, which is
--   what the tie scores if you never shift it.
--   PROMPT was: at each frequency — tuning moves both.
--   PROMPT now: at each frequency. Tuning moves both.
--
-- ADVANCED
--   tune40_amp was identical to tune25_amp (0.1155947595834732): 25 x 16 = 40 x
--   10 = 400 Hz ms, so both evaluate the Ricker at the same argument and one
--   reading answered both fields. It is replaced by the 40 Hz amplitude of a
--   stated 6 ms bed, below the 40 Hz tuning thickness, 0.09535394608974457, read
--   from the Wedge explorer 'Amplitude there' tile at ten decimals with the
--   thickness selector at 6 ms, tol 0.0005.
--   RE-KEY tune40_amp (expected 0.1155947595834732, tol 0.002)
--       -> amp40_at_6ms 'Amplitude of a 6 ms bed at 40 Hz' -, expected 0.09535394608974457, tol 0.0005
--   PROMPT was: the tuning thickness and its peak amplitude at each frequency,
--   PROMPT now: the tuning thickness at each frequency, the peak amplitude at 25
--   Hz tuning, the amplitude of a 6 ms bed at 40 Hz,
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves:
-- seismolord/intermediate, seismolord/advanced. Before it writes, the file
-- counts academy_capstone_attempts on each and REFUSES if any exist, unless D5
-- allowlists that tier with the exact attempt ids (allowlist: empty). Stored
-- scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- seismolord / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 seismolord refused: seismolord/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'cf056461f391f19556c7d8a1c964ca56' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr", "tol": 0.01, "unit": "-", "label": "Correlation at the suggested shift", "expected": 1}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'old'
              when md5(prompt) = '09e39aaf8a6acb6b7b71f47935ec9571' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'new'
              when md5(prompt) = '0586befbe8a90da6228d5b53750c46fb' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w1 seismolord refused: seismolord/intermediate matches neither its published form (prompt md5 cf056461f391f19556c7d8a1c964ca56) nor its W1 form (prompt md5 09e39aaf8a6acb6b7b71f47935ec9571), with the fields this file was generated against';
  end if;

  -- seismolord / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 seismolord refused: seismolord/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '97e4fdfcd54042ae5e5e973bb41e671e' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "tune40_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 40 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'old'
              when md5(prompt) = 'e17e1dac9c11bcfa899daa4fbe875920' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'new'
              when md5(prompt) = '4ccfcca366426ba684682830d039ffe0' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w1 seismolord refused: seismolord/advanced matches neither its published form (prompt md5 97e4fdfcd54042ae5e5e973bb41e671e) nor its W1 form (prompt md5 e17e1dac9c11bcfa899daa4fbe875920), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w1 seismolord: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 seismolord refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'seismolord' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'seismolord/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'seismolord/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 seismolord refused: seismolord/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 seismolord: seismolord/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 seismolord refused: seismolord/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'seismolord' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'seismolord/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'seismolord/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 seismolord refused: seismolord/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 seismolord: seismolord/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 seismolord refused: seismolord/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'The observed seismic trace is the 25 Hz synthetic arriving late by a lag this brief does not state. Run the bulk-shift scan and read the panel: the suggested shift, and the correlation at zero lag, which is what the tie scores if you never shift it. Then flip the wavelet between 15 and 40 Hz and report the strongest synthetic amplitude and its time at each frequency. Tuning moves both.',
           fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb
     where app_slug = 'seismolord' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 seismolord refused: seismolord/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '09e39aaf8a6acb6b7b71f47935ec9571' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb)
        or (md5(prompt) = '0586befbe8a90da6228d5b53750c46fb' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 seismolord refused: seismolord/intermediate does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Model the SAND top and base as an equal and opposite reflection pair (RC +0.08 / -0.08) in a wedge from 0 to 60 ms at a 2 ms sample rate. Read the tuning panel at 25 Hz and 40 Hz: the tuning thickness at each frequency, the peak amplitude at 25 Hz tuning, the amplitude of a 6 ms bed at 40 Hz, the ratio of the 25 Hz tuning amplitude to the isolated-reflector level on the thick end of the same run, and the Kallweit-Wood theoretical tuning thickness sqrt(6)/(2*pi*f) at 25 Hz.',
           fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb
     where app_slug = 'seismolord' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 seismolord refused: seismolord/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'e17e1dac9c11bcfa899daa4fbe875920' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb)
        or (md5(prompt) = '4ccfcca366426ba684682830d039ffe0' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active) is not true then
    raise exception 'w1 seismolord refused: seismolord/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 seismolord: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
